<template>
 <div class="practice-library">
  <div class="practice-heading"><div><h1 class="page-title">练习卡</h1><p class="page-sub">把资料变成可独立作答、持续复习的卡片</p></div><button @click="$router.push({path:'/review',query:{tab:'cards'}})">开始练习卡复习 · {{ due }}</button></div>
  <p v-if="error" class="practice-notice error" role="alert">{{ error }} <button @click="load">重新加载</button></p><p v-if="notice" class="practice-notice" role="status">{{ notice }}</p>
  <section class="card practice-toolbar">
   <label>来源资料<select :value="sourceKey" @change="changeSource($event)" aria-label="练习卡来源"><option value="">全部资料（制作前选择来源）</option><option v-for="e in sources" :key="e.key" :value="e.key">{{ e.title }}</option></select></label>
   <div class="practice-actions"><button @click="manual" :disabled="!sourceKey||working">手动新建卡片</button><button @click="fromBuiltin" :disabled="!sourceKey||working">把自测存成卡片</button><label>生成数量<select v-model.number="count" aria-label="候选卡数量"><option :value="1">1 张</option><option :value="3">3 张</option><option :value="5">5 张</option></select></label><button class="primary" @click="generate" :disabled="!sourceKey||working">{{ generating?'正在生成候选卡…':'AI 生成候选卡' }}</button><button v-if="generating" @click="stop">停止生成</button></div>
  </section>
  <section v-if="candidates.length" class="card practice-candidates" aria-label="候选练习卡">
   <h2>审阅候选卡</h2><p>核对题目、答案和依据，修改后勾选保存。候选题尚未写入资料库。</p>
   <div v-for="(candidate,index) in candidates" :key="candidate.localId" class="practice-candidate"><label><input type="checkbox" v-model="candidate.selected" :disabled="saving" /> 保存第 {{ index+1 }} 张 · {{ candidate.origin==='ai'?'AI 原创候选':candidate.origin==='builtin'?'来自内置自测':'手动制作' }}</label><PracticeCardEditor :disabled="saving" :model-value="candidate" @update:model-value="candidates[index]=$event" /></div>
   <label class="practice-enroll"><input v-model="enroll" :disabled="saving" type="checkbox" /> 保存后加入复习</label><div class="practice-actions"><button class="primary" @click="saveCandidates" :disabled="working||!candidates.some(e=>e.selected)">保存勾选卡片</button><button @click="discardCandidates" :disabled="saving">放弃候选卡</button></div>
  </section>
  <section class="card practice-filters"><input v-model="query" type="search" aria-label="搜索练习卡" placeholder="搜索题目、答案、解析或标签" maxlength="200" /><select v-model="status" aria-label="卡片状态"><option value="active">使用中</option><option value="paused">暂停</option><option value="archived">归档</option><option value="all">全部状态</option></select><select v-model="type" aria-label="筛选卡片题型"><option value="">全部题型</option><option v-for="(label,key) in typeLabels" :key="key" :value="key">{{ label }}</option></select><select v-model="tag" aria-label="筛选练习卡标签"><option value="">全部标签</option><option v-for="t in tags" :key="t">{{ t }}</option></select><span>{{ entries.length }} / {{ total }} 张</span></section>
  <div class="practice-workspace">
   <aside class="card practice-list"><button v-for="e in entries" :key="e.id" class="practice-item" :class="{selected:selected?.id===e.id}" @click="select(e.id)"><small>{{ typeLabels[e.type] }} · {{ e.status==='paused'?'暂停':e.status==='archived'?'归档':e.due?'已加入复习':'尚未加入复习' }}</small><strong>{{ e.question }}</strong><small>{{ e.source_title }}</small><small>{{ e.tags.map(t=>'#'+t).join(' ') }}</small></button><p v-if="!entries.length">没有匹配的练习卡。选择来源资料后可制作第一张。</p></aside>
   <section class="card practice-detail">
    <template v-if="selected">
     <div class="practice-actions"><button v-if="selected.status==='active'" @click="changeState(selected.due?'pause':'enroll')" :disabled="working">{{ selected.due?'暂停复习':'加入复习' }}</button><button v-if="selected.status==='paused'" @click="changeState(selected.due?'resume':'enroll')" :disabled="working">{{ selected.due?'继续复习':'加入复习' }}</button><button v-if="selected.status!=='archived'&&selected.due" @click="changeState('unenroll')" :disabled="working">移出队列</button><button v-if="selected.status!=='archived'" @click="changeState('archive')" :disabled="working">归档卡片</button><button v-else @click="changeState('restore')" :disabled="working">恢复为暂停状态</button></div>
     <h2>{{ selected.question }}</h2><p class="practice-muted">{{ selected.origin==='ai'?'AI 原创 · 请核对内容':selected.origin==='builtin'?'来自资料自测':'手动制作' }} · 版本 {{ selected.revision }} · {{ selected.due?'下次复习 '+new Date(selected.due).toLocaleString():'尚未加入复习' }}</p>
     <p class="practice-source">来源：{{ selected.source_title }} <button @click="openSource">打开资料</button><strong v-if="selected.sourceStatus==='changed'">来源已变化，卡片保留原版本</strong><strong v-if="selected.sourceStatus==='unavailable'">来源暂不可用，卡片与历史仍保留</strong></p>
     <details><summary>查看制作时的来源快照</summary><article class="md-body" v-html="renderMarkdown(selected.source_content)"></article></details>
     <PracticeScheduler :key="selected.id+':'+selected.revision" :card="selected" :disabled="working||editing||!!candidates.length" @busy="trialBusy=$event" @changed="trialChanged" />
     <button v-if="!editing" @click="startEdit">编辑这张卡</button>
     <form v-if="editing" @submit.prevent="saveEdit" class="practice-edit"><p>改变题目、题型、选项或答案后会重新学习，既有作答记录保留。</p><PracticeCardEditor :disabled="saving" v-model="draft" /><div class="practice-actions"><button class="primary" type="submit" :disabled="working">保存卡片修改</button><button type="button" @click="cancelEdit" :disabled="saving">取消修改</button></div></form>
     <template v-else><ol v-if="selected.type==='choice'"><li v-for="option in selected.options" :key="option">{{ option }}</li></ol><h3>答案</h3><article class="md-body" v-html="renderMarkdown(selected.answer)"></article><h3>解析</h3><article class="md-body" v-html="renderMarkdown(selected.explanation)"></article></template>
     <h3>最近作答记录 · {{ history.length }}</h3><p v-if="!history.length">还没有作答记录。</p><details v-for="attempt in history" :key="attempt.id" class="practice-history"><summary>{{ new Date(attempt.reviewed_at).toLocaleString() }} · {{ attempt.fsrs?['没想起','费力想起','正常想起','很轻松'][attempt.fsrs.grade-1]+' · FSRS':['不会','模糊','会用'][attempt.rating] }} · 版本 {{ attempt.card_revision }}</summary><p>当时题目：{{ attempt.snapshot.question }}</p><p>我的答案：{{ attempt.response||'未填写文字，心中作答' }}</p><p>当时答案：{{ attempt.snapshot.answer }}</p><p v-if="attempt.correct!==null">客观对照：{{ attempt.correct?'一致':'不一致' }}</p><p>下次复习：{{ new Date(attempt.due).toLocaleString() }}</p></details>
    </template><p v-else>选择左侧卡片查看题目、来源和作答历史。</p>
   </section>
  </div>
 </div>
</template>
<script setup>
import PracticeScheduler from '../components/PracticeScheduler.vue';
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {useRoute,useRouter,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router';import PracticeCardEditor from '../components/PracticeCardEditor.vue';import {renderMarkdown} from '../utils/md.js';import {createAiTasks} from '../utils/ai-tasks.js';
const route=useRoute(),router=useRouter(),sources=ref([]),sourceKey=ref(typeof route.query.entry==='string'?route.query.entry:''),entries=ref([]),tags=ref([]),total=ref(0),due=ref(0),query=ref(''),status=ref('active'),type=ref(''),tag=ref(''),count=ref(3),candidates=ref([]),enroll=ref(false),selected=ref(null),history=ref([]),editing=ref(false),draft=ref({}),baseline=ref(''),trialBusy=ref(false),saving=ref(false),preparing=ref(false),generating=ref(false),error=ref(''),notice=ref('');
const typeLabels={recall:'问答',translation:'翻译',judgment:'判断',choice:'选择'},tasks=createAiTasks(id=>window.keeper.cancelAi(id));let disposed=false,listVersion=0,detailVersion=0,actionVersion=0,timer,batchOperation=null;
const working=computed(()=>saving.value||generating.value||preparing.value||trialBusy.value),dirty=computed(()=>candidates.value.length>0||(editing.value&&JSON.stringify(draft.value)!==baseline.value));
const clean=value=>JSON.parse(JSON.stringify(value));
const editor=card=>({...card,localId:crypto.randomUUID(),selected:true,optionsText:(card.options||[]).join('\n'),tagsText:(card.tags||[]).join(', ')});
function payload(card){return {type:card.type,question:card.question,answer:card.answer,explanation:card.explanation||'',options:card.type==='choice'?String(card.optionsText||'').split('\n').map(s=>s.trim()).filter(Boolean):[],tags:String(card.tagsText||'').split(/[,，、\n]/).map(s=>s.trim()).filter(Boolean)};}
function canDiscard(){return !saving.value&&!trialBusy.value&&(!dirty.value||window.confirm('练习卡还有未保存内容，确定放弃？'));}
function stop(){++actionVersion;preparing.value=false;tasks.cancel('cards');generating.value=false;}
async function load(){const version=++listVersion;try{const r=await window.keeper.practiceList({query:query.value,status:status.value,type:type.value,tag:tag.value,sourceKey:sourceKey.value});if(disposed||version!==listVersion)return;entries.value=r.entries;tags.value=r.tags;total.value=r.total;due.value=r.due;}catch(e){if(!disposed&&version===listVersion)error.value='卡片加载失败：'+e.message;}}
async function chooseSource(key,approved=false){if(!approved&&!canDiscard())return;stop();candidates.value=[];editing.value=false;sourceKey.value=key;++detailVersion;selected.value=null;history.value=[];error.value='';await load();}
async function changeSource(event){await chooseSource(event.target.value);event.target.value=sourceKey.value;}
async function currentSource(){if(!sourceKey.value)throw Error('请先选择来源资料');return window.keeper.practiceSource(sourceKey.value);}
async function manual(){if(!canDiscard())return;stop();const version=actionVersion;preparing.value=true;editing.value=false;try{const source=await currentSource();if(disposed||version!==actionVersion)return;candidates.value=[editor({type:'recall',question:'',answer:'',explanation:'',options:[],tags:source.tags,sourceKey:source.key,sourceHash:source.sourceHash,origin:'manual'})];notice.value='填写后选择保存；卡片将保留当前资料快照。';error.value='';}catch(e){if(!disposed&&version===actionVersion)error.value=e.message;}finally{if(!disposed&&version===actionVersion)preparing.value=false;}}
async function fromPhrase(){if(!canDiscard())return;stop();const version=actionVersion;preparing.value=true;try{const source=await currentSource();if(disposed||version!==actionVersion)return;if(!source.phrase||source.key!=='phrase:'+route.query.phrase)throw Error('短语来源不匹配');const p=source.phrase;candidates.value=[editor({type:'recall',question:'结合原文，解释短语“'+p.quote+'”在此处的意思。\n\n'+p.context,answer:p.meaning,explanation:(p.note?p.note+'\n\n':'')+'出处：'+p.source_label,options:[],tags:source.tags,sourceKey:source.key,sourceHash:source.sourceHash,origin:'manual'})];notice.value='已整理为短语候选卡，请核对题目和释义后选择保存。';}catch(e){if(!disposed&&version===actionVersion)error.value=e.message;}finally{if(!disposed&&version===actionVersion)preparing.value=false;}}
async function fromBuiltin(){if(!canDiscard())return;stop();const version=actionVersion;preparing.value=true;editing.value=false;try{const source=await currentSource();if(disposed||version!==actionVersion)return;const start=source.content.indexOf('**自测**'),end=source.content.indexOf('**答案与依据**',start);if(start<0||end<=start)throw Error('当前资料没有预置自测，可以手动新建或由 AI 生成');candidates.value=[editor({type:'recall',question:source.content.slice(start+6,end).replace(/^[：:\s]+/,'').trim(),answer:source.content.slice(end+9).replace(/^[：:\s]+/,'').trim(),explanation:'请结合来源资料核对规则与例句。',options:[],tags:source.tags,sourceKey:source.key,sourceHash:source.sourceHash,origin:'builtin'})];notice.value='已整理为候选卡，请审阅后保存。';error.value='';}catch(e){if(!disposed&&version===actionVersion)error.value=e.message;}finally{if(!disposed&&version===actionVersion)preparing.value=false;}}
async function generate(){if(!canDiscard())return;stop();candidates.value=[];editing.value=false;const key=sourceKey.value,task=tasks.start('cards');generating.value=true;error.value='';notice.value='';try{const r=await window.keeper.practiceGenerate({sourceKey:key,count:count.value},task.id);if(!task.isCurrent()||sourceKey.value!==key)return;if(!r.ok)throw Error(r.error==='no_key'?'请先在设置配置 AI 服务。':r.error);candidates.value=r.cards.map(card=>editor({...card,sourceKey:key,sourceHash:r.sourceHash,origin:'ai'}));notice.value='生成结果仅为候选卡，尚未保存。请核对每张卡的答案与依据。';}catch(e){if(task.isCurrent())error.value=e.message;}finally{if(task.isCurrent())generating.value=false;task.finish();}}
function discardCandidates(){if(!canDiscard())return;stop();candidates.value=[];batchOperation=null;notice.value='已放弃未保存的候选卡。';}
async function saveCandidates(){if(working.value)return;const cards=candidates.value.filter(e=>e.selected).map(e=>({...payload(e),sourceKey:e.sourceKey,sourceHash:e.sourceHash,origin:e.origin}));if(!cards.length)return;const signature=JSON.stringify([cards,enroll.value]);if(batchOperation?.signature!==signature)batchOperation={id:crypto.randomUUID(),signature};saving.value=true;error.value='';try{const r=await window.keeper.practiceSaveBatch(clean({cards,enroll:enroll.value,operationId:batchOperation.id}));if(!r.ok)throw Error(r.error);candidates.value=[];batchOperation=null;notice.value=`已保存 ${r.created.length} 张卡片，跳过 ${r.duplicates.length} 张重复题。`;await load();const id=r.created[0]||r.duplicates[0]?.id;if(id)await select(id,true);}catch(e){error.value='保存失败，候选卡仍保留：'+e.message;}finally{saving.value=false;}}
async function select(id,force=false){if(!force&&!canDiscard())return;if(!force){stop();candidates.value=[];}const version=++detailVersion;editing.value=false;try{const [card,logs]=await Promise.all([window.keeper.practiceGet(id),window.keeper.practiceHistory(id)]);if(disposed||version!==detailVersion)return;selected.value=card;history.value=logs;}catch(e){if(!disposed&&version===detailVersion)error.value=e.message;}}
function startEdit(){if(!canDiscard())return;stop();candidates.value=[];draft.value=editor(selected.value);baseline.value=JSON.stringify(draft.value);editing.value=true;}
function cancelEdit(){if(canDiscard())editing.value=false;}
async function saveEdit(){if(working.value)return;const card=selected.value;saving.value=true;error.value='';try{const r=await window.keeper.practiceSave(clean({...payload(draft.value),id:card.id,expectedRevision:card.revision}));if(!r.ok)throw Error(r.error);editing.value=false;notice.value=r.relearning?'卡片已修改，重新学习；旧作答记录保留。':'卡片已保存。';await load();await select(card.id,true);}catch(e){error.value='修改未保存：'+e.message;}finally{saving.value=false;}}
async function changeState(action){if(working.value||!canDiscard())return;if(action==='archive'&&!window.confirm('归档这张卡？历史会保留，可恢复。'))return;const card=selected.value;saving.value=true;try{const r=await window.keeper.practiceState({id:card.id,expectedRevision:card.revision,action});if(!r.ok)throw Error(r.error);editing.value=false;candidates.value=[];notice.value='卡片状态已更新。';await load();await select(card.id,true);}catch(e){error.value=e.message;}finally{saving.value=false;}}
async function trialChanged(result){trialBusy.value=false;notice.value=(result.action==='enable'?'当前卡已启用 FSRS 试用。':'已回到原调度，试用作答保留。')+' 备份：'+result.backupPath;await load();await select(result.id,true);}
async function openSource(){try{if(selected.value.source_key.startsWith('phrase:')){const id=selected.value.source_key.slice(7);await window.keeper.practiceSource(selected.value.source_key);await router.push({path:'/phrases',query:{phrase:id}});return;}await window.keeper.kbGet(selected.value.source_key);await router.push({path:'/knowledge',query:{entry:selected.value.source_key}});}catch(e){error.value='来源暂不可用，仍可查看上方保存的来源快照。';}}
watch([query,status,type,tag],()=>{clearTimeout(timer);timer=setTimeout(load,180);});
watch(()=>route.query.entry,value=>{const key=typeof value==='string'?value:'';if(key!==sourceKey.value)chooseSource(key,true);});
watch(()=>route.query.card,id=>{if(typeof id==='string')select(id,true);});
watch(()=>route.query.phrase,async id=>{if(typeof id==='string'){await chooseSource('phrase:'+id,true);await fromPhrase();}},{flush:'post'});
onBeforeRouteLeave(()=>{if(!canDiscard())return false;stop();return true;});onBeforeRouteUpdate(()=>{if(!canDiscard())return false;stop();candidates.value=[];editing.value=false;return true;});
onMounted(async()=>{try{sources.value=(await window.keeper.practiceSources()).entries;}catch(e){error.value=e.message;}await load();if(typeof route.query.card==='string')await select(route.query.card,true);else if(typeof route.query.phrase==='string')await fromPhrase();});
onBeforeUnmount(()=>{disposed=true;++listVersion;++detailVersion;clearTimeout(timer);stop();});
</script>
<style scoped>
.practice-heading,.practice-actions,.practice-filters{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.practice-heading{justify-content:space-between;margin-bottom:18px}.practice-toolbar,.practice-candidates,.practice-filters,.practice-detail{padding:20px;margin-bottom:16px}.practice-toolbar>label{display:block;font-size:13px}.practice-toolbar select,.practice-filters input,.practice-filters select{max-width:100%;padding:8px;border:1px solid var(--border);border-radius:7px;background:var(--card);color:var(--text)}.practice-toolbar>label>select{display:block;width:100%;margin:7px 0 12px}.practice-actions{margin:12px 0}.practice-actions button{font-size:12px}.practice-candidates h2,.practice-detail h2{font-size:20px;line-height:1.6;overflow-wrap:anywhere}.practice-candidates p,.practice-edit>p{font-size:13px;color:var(--muted)}.practice-candidate{padding:18px 0;border-top:1px solid var(--border)}.practice-candidate>label{display:block;margin-bottom:12px}.practice-enroll{display:block;margin-top:16px}.practice-filters input{flex:1;min-width:170px}.practice-filters span,.practice-muted{font-size:12px;color:var(--muted)}.practice-workspace{display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px}.practice-list{padding:8px;max-height:65vh;overflow:auto;align-self:start;position:sticky;top:16px}.practice-item{display:flex;flex-direction:column;gap:7px;width:100%;padding:13px;text-align:left;background:transparent;border:1px solid transparent;margin:4px 0;border-radius:8px;overflow-wrap:anywhere}.practice-item.selected{background:var(--accent-soft);border-color:var(--accent)}.practice-item small{color:var(--muted);font-size:11px}.practice-detail{min-width:0}.practice-detail article{line-height:1.85;overflow-wrap:anywhere;margin:12px 0}.practice-detail details{margin:14px 0;font-size:13px}.practice-source{font-size:12px;padding:10px;background:var(--accent-soft);border-radius:8px}.practice-source strong{display:block;margin-top:7px}.practice-source button{font-size:11px}.practice-notice{padding:12px;background:var(--accent-soft);border-radius:8px;font-size:13px}.error{color:var(--red)}.practice-history{border-top:1px solid var(--border);padding-top:10px}.practice-history p{white-space:pre-wrap;overflow-wrap:anywhere}@media(max-width:900px){.practice-workspace{grid-template-columns:1fr}.practice-list{position:static;max-height:250px}}
</style>
